  "Alur Kampanye": "Campaign Flow",
  "Alur: partner menolak → Tauthub mencari media alternatif (media yang sudah dicoba untuk artikel yang sama dieksklusi, standard check tetap dijalankan) → publikasi pengganti dibuat otomatis → klien diberi notifikasi. Jika melebihi batas beruntun atau tidak ada kandidat, publikasi tetap ditolak tanpa penggantian.": "Flow: partner rejects → Tauthub looks for alternative media (media already tried for the same article are excluded, standard checks still run) → a replacement publication is created automatically → the client is notified. If the consecutive limit is exceeded or there are no candidates, the publication stays rejected without replacement.",
