  "Catatan untuk mitra (opsional)": "Note for partner (optional)",
  "Catatan: diskon dihitung per media saat reservasi TC publikasi (pembulatan ke bawah per media, minimal 1 TC bila harga asli > 0). Transaksi lama tidak terpengaruh — hanya publikasi baru yang membawa package_id memakai diskon ini.": "Note: the discount is calculated per media when reserving publication TC (rounded down per media, minimum 1 TC if the original price > 0). Existing transactions are unaffected — only new publications carrying a package_id use this discount.",
  "Catatan: job analisis/verifikasi diproses oleh queue worker di background. Skor direkalkulasi otomatis setelah tiap job selesai.": "Note: analysis/verification jobs are processed by a background queue worker. Scores are recalculated automatically after each job finishes.",
  "Catatan: menyimpan standar brand akan mengembalikan rate tier brand ke global Tauthub. Perubahan tidak mengubah angka historis yang sudah dihitung.": "Note: saving brand standards resets the brand's tier rates to the global Tauthub ones. The change does not alter historical figures that have already been calculated.",
