  "Cepat dan hemat. Cocok untuk draf awal & artikel rutin.": "Fast and affordable. Great for early drafts & routine articles.",
  "Ceritakan dulu apa yang Anda miliki — bahan, artikel, atau belum ada apa-apa. Tauthub menyesuaikan pertanyaan, menilai kelengkapan, lalu mengantar Anda ke AI Writer.": "First tell us what you have — materials, articles, or nothing at all. Tauthub adapts the questions, assesses completeness, then takes you to the AI Writer.",
