  "Data ini diperlukan sejak awal agar Agent Matchmaker hanya mencarikan media yang memperbolehkan tanam link, dan Agent Writer bisa menyusun narasi organik menuju link tersebut.": "This data is needed up front so the Matchmaker Agent only looks for media that allow link insertion, and the Writer Agent can build an organic narrative leading to that link.",
