  "Data rekening atau e-wallet belum diisi.": "Bank account or e-wallet details have not been filled in.",
  "Data terisi setelah artikel terbit dan pembaca mengakses halaman.": "Data is populated after the article is published and readers access the page.",
  "Default 60 hari. Setelah kontrak berakhir, hak VIP Reguler (fee per-domain) nonaktif. Domain yang masuk sebelum berakhir tetap dibayar.": "Default 60 days. After the contract ends, the Regular VIP entitlement (per-domain fee) is deactivated. Domains submitted before it ends are still paid.",
  "Default kualitas per tier dipakai saat media belum punya media_quality_score sendiri. Relevance per kategori dipakai kolom Relevansi di tabel per-media (partial match case-insensitive).": "The default quality per tier is used when a media outlet does not yet have its own media_quality_score. The relevance per category is used by the Relevance column in the per-media table (case-insensitive partial match).",
  "Definisikan kuesioner & bobot readiness. Total bobot disarankan 100.": "Define the readiness questionnaire & weights. A total weight of 100 is recommended.",
  "Dengan 2FA aktif, setiap login membutuhkan password dan kode 6 digit dari aplikasi autentikator, melindungi akun Anda meski password bocor.": "With 2FA active, every login requires your password and a 6-digit code from the authenticator app, protecting your account even if the password leaks.",
  "Dengan menyetujui, Anda memberi Tauthub izin mengirim artikel klien ke akun/website media Anda melalui kanal yang Anda hubungkan di halaman ini (WordPress, Web Custom, atau Blogger).": "By agreeing, you give Tauthub permission to send client articles to your media accounts/websites through the channels you connect on this page (WordPress, Custom Web, or Blogger).",
