  "Halaman artikel sudah tidak ada di situs media (404/410). Tekan Ganti Artikel untuk membuat pengganti di media lain.": "The article page is no longer available on the media site (404/410). Press Replace Article to create a replacement on another media outlet.",
  "Halaman berikutnya": "Next page",
  "Halaman challenge bot": "Bot challenge page",
  "Halaman ini akan diperbarui otomatis saat pembayaran terverifikasi.": "This page will update automatically once the payment is verified.",
  "Halaman ini hanya dapat diakses oleh Super Admin.": "This page can only be accessed by a Super Admin.",
  "Halaman ini hanya tersedia untuk pengujian lokal. Klik tombol di bawah untuk mengirim callback": "This page is only available for local testing. Click the button below to send a callback",
  "Halaman ini menjaga garansi tayang 12 bulan: sistem memeriksa apakah artikel yang sudah terbit di situs media mitra masih bisa dibuka. Kalau ada halaman yang hilang, artikel itu ditandai di baris daftar supaya bisa segera diganti di media lain. Pengecekan ulang berjalan otomatis tiap 7 hari dan bisa diantrekan manual lewat tombol Cek Sekarang.": "This page upholds the 12-month publication guarantee: the system checks whether articles already published on partner media sites can still be opened. If a page is gone, that article is flagged in its list row so it can be replaced on another media outlet right away. Rechecks run automatically every 7 days and can be queued manually with the Check Now button.",
  "Halaman ini tidak tersedia untuk brand. Kembali ke beranda untuk melihat ringkasan dan menu lengkap.": "This page is not available for brands. Return to the home page to see the summary and full menu.",
