  "Hanya bisa dihapus bila media tidak punya riwayat publikasi, earning, atau rencana publikasi. Data terkait (standar konten, API key, revenue share, keanggotaan paket media) ikut terhapus.": "Can only be deleted if the media has no publication history, earnings, or publication plans. Related data (content standards, API keys, revenue share, media package membership) will also be deleted.",
