  "Harga klien (IDR)": "Client price (IDR)",
  "Harga klien = harga mitra × (1 + markup%). Nilai disimpan sekali di database dan dibaca lewat cache server (bukan query berat tiap halaman) — katalog klien, kredit TC, dan checkout langsung memakai nilai baru begitu disimpan. Publikasi yang sudah dibuat tidak berubah (harganya ter-snapshot saat dibuat).": "Client price = partner price × (1 + markup%). The value is stored once in the database and read through the server cache (not a heavy query on every page) — the client catalog, TC credits, and checkout use the new value as soon as it is saved. Publications already created do not change (their price is snapshotted at creation).",
  "Harga mitra (IDR)": "Partner price (IDR)",
  "Harga mitra + markup": "Partner price + markup",
  "Harga negosiasi (IDR)": "Negotiated price (IDR)",
  "Harga negosiasi wajib diisi.": "Negotiated price is required.",
  "Hasil crawl otomatis per media mitra aktif. Scheduler mengantre crawl baru tiap menit; gagal diulang setelah 24 jam (maks 2x), dan media yang hasilnya lebih tua dari 3 bulan di-crawl ulang.": "Automatic crawl results per active partner media. The scheduler queues a new crawl every minute; failures are retried after 24 hours (max 2x), and media whose results are older than 3 months are re-crawled.",
