  "Isi Endpoint URL + API Key lalu Simpan untuk mengaktifkan distribusi ke website custom ini.": "Enter the Endpoint URL + API Key, then Save to enable distribution to this custom website.",
  "Isi bahan (fakta/produk/masalah), lalu Test. Artikel digenerate dari prompt angle di atas + bahan, lalu dianalisis apakah artikel benar-benar sesuai angle. Hanya testing — tidak membuat campaign.": "Fill in the material (facts/product/problem), then Test. The article is generated from the angle prompt above + the material, then analyzed to see whether the article truly matches the angle. Testing only — no campaign is created.",
  "Isi dengan contoh untuk angle": "Fill with an example for the angle",
  "Isi dengan IP publik VPS tempat aplikasi ini berjalan. Kalau dikosongkan, sistem mendeteksi lewat layanan echo IP saat ada mitra yang diblokir — tetapi nilai manual lebih dapat diandalkan karena tidak bergantung layanan luar.": "Enter the public IP of the VPS where this application runs. If left blank, the system detects it via an IP echo service when a partner is blocked — but a manual value is more reliable since it does not depend on an external service.",
  "Isi manual — AI tidak memiliki data narasumber yang akurat dari situs.": "Fill in manually — the AI has no accurate source data from the site.",
  "Isi sebanyak yang Anda tahu": "Fill in as much as you know",
  "Isi tujuan penerimaan dana di profil sebelum mengajukan penarikan.": "Fill in the fund receiving destination in your profile before requesting a withdrawal.",
