  "Jadwal mengirim media ke Mitra sesuai pengaturan — hanya distribusi ke Mitra, waktu terbit aktual dikelola Mitra.": "Schedule for sending media to Partners per your settings — distribution to Partners only; actual publish time is managed by the Partner.",
  "Jadwal terbit di media mitra": "Publish schedule on partner media",
  "Jalankan analisis untuk melihat performa dan Core Web Vitals website.": "Run an analysis to see the website performance and Core Web Vitals.",
  "Jalankan ulang analisis (message + sentiment + verifikasi URL) dan hitung ulang skor untuk publikasi published yang sudah ada sebelum fitur ini.": "Re-run the analysis (message + sentiment + URL verification) and recalculate scores for existing published publications created before this feature.",
  "Jatah generate per artikel (1-999, kosongkan = default 3):": "Generation quota per article (1-999, leave empty = default 3):",
  "Jawab singkat saja (1 kalimat). Pertanyaan menyesuaikan angle yang Anda pilih di Jalur Distribusi; AI akan meramunya dengan Konteks Bisnis URL Anda menjadi artikel berbobot.": "Answer briefly (1 sentence). Questions adapt to the angle you choose in the Distribution Path; the AI will blend them with your URL's Business Context into a substantial article.",
