  "Masukkan nominal rupiah penuh — saldo brand akan dikurangi sebesar angka ini, maksimal Rp10.000.000.000.": "Enter the full rupiah amount — the brand balance will be reduced by this amount, up to a maximum of Rp10,000,000,000.",
  "Nominal rupiah penuh, maksimal Rp10.000.000.000 per penyesuaian.": "Full rupiah amount, maximum Rp10,000,000,000 per adjustment.",
  "Jumlah saldo harus angka positif.": "Balance amount must be a positive number.",
  "Saldo internal Client dalam rupiah. Client, Partner, dan Admin melihat nominal yang sama. Nilai ini bukan uang yang dapat dicairkan.": "Client's internal balance in rupiah. Client, Partner, and Admin all see the same amounts. This balance is not withdrawable cash.",
  "Kredit (+ saldo)": "Credit (+balance)",
