  "Klien melaporkan topup yang gagal (pembayaran sukses tapi saldo tidak masuk). Setujui untuk menambahkan saldo manual ke wallet brand.": "Clients report failed top-ups (payment succeeded but the balance never arrived). Approve to manually add the balance to the brand wallet.",
  "cth: Terverifikasi — saldo ditambahkan. / Data tidak cocok dengan transaksi.": "e.g.: Verified — balance added. / Transaction details do not match.",
  "Bundel media yang bisa dipilih klien satu klik. Diskon persen (0–100) benar-benar dipakai saat billing saldo publikasi — setiap media anggota dihitung dengan harga diskon, dan klien melihat 'Hemat X' di tombol paket. Paket yang dihapus otomatis hilang dari daftar klien.": "Media bundles clients can order in one click. The percentage discount (0–100) is applied to publication billing — each member media is priced at the discounted price, and clients see 'Save X' on the bundle button. Deleted bundles disappear from the client list automatically.",
  "Catatan: diskon dihitung per media saat reservasi saldo publikasi (pembulatan ke bawah per media, minimal Rp1 bila harga asli > 0). Transaksi lama tidak terpengaruh — hanya publikasi baru yang membawa package_id memakai diskon ini.": "Note: the discount is applied per media when reserving publication balance (floored per media, minimum Rp1 when the original price is > 0). Existing transactions are unaffected — only new publications carrying a package_id use this discount.",
  "Harga klien = harga mitra × (1 + markup%). Nilai disimpan sekali di database dan dibaca lewat cache server (bukan query berat tiap halaman) — katalog klien, kredit saldo, dan checkout langsung memakai nilai baru begitu disimpan. Publikasi yang sudah dibuat tidak berubah (harganya ter-snapshot saat dibuat).": "Client price = partner price × (1 + markup%). The value is stored once in the database and read through a server cache (not a heavy query per page) — the client catalog, balance credit, and checkout use the new value as soon as it is saved. Existing publications do not change (their price is snapshotted when created).",
  "Dokumen ini dihasilkan dari data sistem pada saat dicetak. Angka artikel, media terbit, dan saldo terpakai adalah hasil penjumlahan agregat basis data (publikasi terbit, ledger debit saldo) milik kampanye ini.": "This document is generated from system data at print time. Article, published media, and used-balance figures are database aggregates (published publications, balance ledger debits) belonging to this campaign.",
  "Masukkan angka positif — saldo brand akan dikurangi sebesar angka ini, maksimal 10.000.000 TC.": "Enter a positive number — the brand balance will be reduced by this amount, up to a maximum of 10,000,000 TC.",
