  "Satu angle = satu prompt aktif yang bisa diedit selamanya. Hapus versi lama yang tidak dipakai untuk hemat resource.": "One angle = one active prompt that can be edited forever. Delete unused old versions to save resources.",
  "Satu baris = satu order distribusi (satu media). Nomor order per media dan nomor kampanye induknya dipakai untuk melacak masalah; detail teknis (attempts, job, retry) ada di halaman publikasi.": "One row = one distribution order (one media). The per-media order number and its parent campaign number are used to trace issues; technical details (attempts, job, retry) are on the publication page.",
  "Satu batch = satu sumber → satu artikel per media dengan sudut pandang berbeda (PRNG seeded). Klik varian untuk melihat riwayat job generasi di queue.": "One batch = one source → one article per media with a different angle (PRNG seeded). Click a variant to view the generation job history in the queue.",
