  "Sebab kegagalan verifikasi domain mitra, tersimpan dari hasil pengecekan terakhir. Pakai ini untuk membedakan situs yang mati, situs yang diblokir, dan kode verifikasi yang salah tempel. Default hanya menampilkan domain yang belum terverifikasi.": "Why partner domain verification failed, stored from the last check. Use this to tell apart dead sites, blocked sites, and verification codes pasted incorrectly. By default only unverified domains are shown.",
