  "Sindikasi Konten menyalurkan artikel mitra melalui RSS feed ke mitra lain atau publisher eksternal.": "Content Syndication distributes partner articles via RSS feed to other partners or external publishers.",
  "Sisipkan video atau peta": "Insert video or map",
  "Sistem Deep Scan dan QC": "Deep Scan and QC System",
  "Sistem membuka halaman artikel di situs media mitra untuk memastikan halamannya masih bisa diakses. Kalau halaman tidak ditemukan (Hilang 404), tekan tombol Ganti Artikel pada baris tersebut untuk membuat artikel pengganti di media lain. Status Tak Terjangkau tidak dihitung sebagai artikel hilang, karena situsnya mungkin hanya sedang memblokir akses atau mati sementara.": "The system opens the article page on the partner media site to verify it is still accessible. If the page is not found (404 Missing), press the Replace Article button on that row to create a replacement article on another media. Unreachable status does not count as a missing article, since the site may simply be blocking access or temporarily down.",
  "Sistem mendeteksi adanya perubahan manual pada artikel di Agent 3. Gatekeeper harus memindai ulang setiap artikel secara individual untuk mencegah penyisipan konten ilegal (Judi, SARA) yang dapat merugikan reputasi media mitra.": "The system detects manual changes to articles in Agent 3. The Gatekeeper must rescan each article individually to prevent the insertion of illegal content (Gambling, SARA) that could damage the reputation of partner media.",
  "Situs media menolak akses atau sedang error. Belum tentu hilang, jadi tidak dihitung sebagai artikel hilang.": "The media site is refusing access or is erroring. It may not be gone, so it is not counted as a missing article.",
  "Situs menolak akses atau sedang bermasalah": "The site denied access or is having issues",
  "Situs menolak akses atau sedang bermasalah — belum tentu hilang": "Site refuses access or is having issues — not necessarily gone",
  "Situs mitra bisa dihubungi dan penanda verifikasi domain ditemukan.": "Partner site is reachable and the domain verification marker was found.",
  "Situs mitra hidup, tetapi penanda verifikasi domain tidak ditemukan lagi di halamannya.": "The partner site is up, but the domain verification marker is no longer found on its page.",
  "Situs mitra tidak bisa dihubungi, sehingga artikel yang terbit di sana ikut tidak bisa dibuka.": "The partner site cannot be reached, so articles published there cannot be opened either.",
  "Skor dari provider pihak ketiga (Moz metrics via RapidAPI). Bukan jaminan kualitas media, gunakan sebagai referensi.": "Score from a third-party provider (Moz metrics via RapidAPI). Not a guarantee of media quality; use as a reference.",
  "Skor performa belum tersedia.": "Performance score is not available yet.",
  "Stabilitas posisi elemen saat halaman dimuat.": "Stability of element positions while the page loads.",
  "Standarisasi PR adalah engine internal Tauthub — klien tidak mengatur ini. Override per brand: rate per 1.000 estimasi reach khusus untuk brand ini. Kosong = pakai standar global Tauthub (diatur di menu PR Calculator).": "PR standardization is Tauthub's internal engine — clients do not control this. Per-brand override: rate per 1,000 estimated reach specific to this brand. Empty = use Tauthub's global standard (set in the PR Calculator menu).",
  "Standarisasi PR untuk semua dashboard klien — klien tidak mengatur ini, mereka hanya menerima angka. Estimated PR value = nilai media + Σ(reach tier ÷ 1.000 × rate tier). Rate tier kosong = memakai rate global. Diterapkan saat laporan dihitung; angka historis tidak berubah otomatis. Override per brand dikelola di menu": "PR standardization for all client dashboards — clients do not configure this, they only receive the numbers. Estimated PR value = media value + Σ(reach tier ÷ 1.000 × rate tier). Empty rate tier = uses the global rate. Applied when the report is calculated; historical numbers do not change automatically. Per-brand overrides are managed in the menu",
