  "Garansi tayang mengikuti kebijakan media": "The publishing guarantee follows the media policy",
  "— 12 bulan, atau permanen bila medianya menjamin tautan tidak pernah dilepas. Masa garansi berlaku sejak tanggal tayang, dan eksklusif untuk": "— 12 months, or permanent if the media guarantees the link is never removed. The guarantee runs from the publish date and is exclusive to",
  "Semua artikel yang tayang dalam masa garansi medianya masih terpantau bisa diakses (12 bulan, atau tanpa batas untuk media dengan tautan permanen). Halaman ini akan menampilkan artikel begitu ada yang hilang atau tidak terjangkau.": "Every article published within its media's guarantee period is still monitored and reachable (12 months, or unlimited for media with permanent links). This page lists articles as soon as any go missing or become unreachable.",
  "Halaman ini menjaga garansi tayang setiap artikel: sistem memeriksa apakah artikel yang sudah terbit di situs media mitra masih bisa dibuka selama masa garansi medianya (12 bulan, atau tanpa batas bila medianya menjamin tautan permanen). Kalau ada halaman yang hilang, artikel itu ditandai di baris daftar supaya bisa segera diganti di media lain. Pengecekan ulang berjalan otomatis tiap 7 hari dan bisa diantrekan manual lewat tombol Cek Sekarang.": "This page upholds each article's publishing guarantee: the system checks whether articles already published on partner media sites can still be opened for as long as the media's guarantee runs (12 months, or unlimited when the media guarantees a permanent link). If a page is gone, that article is flagged in its list row so it can be replaced on another media outlet right away. Rechecks run automatically every 7 days and can be queued manually with the Check Now button.",
  "Klaim garansi dari klien. Periksa kondisi domain, hubungi pemilik domain, lalu kembalikan saldo bila masalahnya tidak bisa diselesaikan. Kelayakan (masih dalam masa garansi media — 12 bulan atau permanen, media terverifikasi, dan kerusakan 404 atau tautan dicabut) sudah diperiksa server.": "A guarantee claim from the client. Check the domain's condition, contact the domain owner, then refund the balance if the problem cannot be resolved. Eligibility (still within the media's guarantee — 12 months or permanent, verified media, and a 404 or removed link) has already been checked by the server.",
  "Artikel dipantau selama masa garansi medianya: 12 bulan sejak terbit, atau tanpa batas bila medianya menjamin tautan permanen. Status Hilang (404) berarti halaman sudah tidak ada dan bisa diganti ke media lain; Tak Terjangkau berarti situs menolak akses atau sedang error dan tidak dianggap hilang.": "Articles are monitored for the duration of their media's guarantee: 12 months from publication, or unlimited when the media guarantees a permanent link. Missing (404) status means the page no longer exists and can be replaced on another media; Unreachable means the site denies access or is erroring and is not considered missing.",
