/**
 * Terjemahkan frasa UI. Saat locale = 'en', cari di PHRASE_EN;
 * tidak ketemu → kembalikan teks asli (aman, tidak pernah kosong).
 * Membaca `locale` ($state) saat render, jadi template ikut reaktif.
 */
export function tr(text: string): string {
  if (getLocale() !== 'en') return text;
  return PHRASE_EN[text] ?? text;}
